          in.beginObject();
          int year = 0;
          int month = 0;
          int dayOfMonth = 0;
          int hourOfDay = 0;
          int minute = 0;
          int second = 0;
          while (in.peek() != JsonToken.END_OBJECT) {
            String name = in.nextName();
            int value = in.nextInt();
            switch (name) {
              case YEAR:
                year = value;
                break;
              case MONTH:
                month = value;
                break;
              case DAY_OF_MONTH:
                dayOfMonth = value;
                break;
              case HOUR_OF_DAY:
                hourOfDay = value;
                break;
              case MINUTE:
                minute = value;
                break;
              case SECOND:
                second = value;
                break;
              default:
                // Ignore unknown JSON property
            }
          }
          in.endObject();
          return new GregorianCalendar(year, month, dayOfMonth, hourOfDay, minute, second);
        }

