    JsonSyntaxException e =
        assertThrows(JsonSyntaxException.class, () -> gson.fromJson(json2, RecursiveClass.class));
    assertThat(e).hasCauseThat().isInstanceOf(MalformedJsonException.class);
    assertThat(e)
