        .hasMessageThat()
        .isEqualTo(
            "Attempted to serialize java.lang.Class: java.lang.String. Forgot to register a type"
                + " adapter?\n"
                + "See https://github.com/google/gson/blob/main/Troubleshooting.md#java-lang-class-unsupported");

