@Test
  public void testCustomSerializerForSpecificMapType() {
    Type type = GsonTypes.newParameterizedTypeWithOwner(null, Map.class, String.class, Long.class);
    Gson gson =
        new GsonBuilder()
            .registerTypeAdapter(
                type,
                (JsonSerializer<Map<String, Long>>)
                    (src, typeOfSrc, context) -> {
                      JsonArray array = new JsonArray();
                      for (long value : src.values()) {
                        array.add(new JsonPrimitive(value));
                      }
                      return array;
                    })
            .create();

    Map<String, Long> src = new LinkedHashMap<>();
    src.put("one", 1L);
    src.put("two", 2L);
    src.put("three", 3L);

    assertThat(gson.toJson(src, type)).isEqualTo("[1,2,3]");
  }

