@Override
    public void parse(char[] data, Document document) throws Exception {
      JsonReader jsonReader = new JsonReader(new CharArrayReader(data));
      readToken(jsonReader);
      jsonReader.close();
    }

private static void readToken(JsonReader reader) throws IOException {
      while (true) {
        switch (reader.peek()) {
          case BEGIN_ARRAY:
            reader.beginArray();
            break;
          case END_ARRAY:
            reader.endArray();
            break;
          case BEGIN_OBJECT:
            reader.beginObject();
            break;
          case END_OBJECT:
            reader.endObject();
            break;
          case NAME:
            String unusedName = reader.nextName();
            break;
          case BOOLEAN:
            boolean unusedBoolean = reader.nextBoolean();
            break;
          case NULL:
            reader.nextNull();
            break;
          case NUMBER:
            long unusedLong = reader.nextLong();
            break;
          case STRING:
            String unusedString = reader.nextString();
            break;
          case END_DOCUMENT:
            return;
        }
      }
    }

@Override
    public void parse(char[] data, Document document) throws Exception {
      JsonReader jsonReader = new JsonReader(new CharArrayReader(data));
      jsonReader.skipValue();
      jsonReader.close();
    }

@Override
    public void parse(char[] data, Document document) throws Exception {
      JsonFactory jsonFactory =
          new JsonFactoryBuilder()
              .configure(JsonFactory.Feature.CANONICALIZE_FIELD_NAMES, false)
              .build();
      com.fasterxml.jackson.core.JsonParser jp =
          jsonFactory.createParser(new CharArrayReader(data));
      int depth = 0;
      do {
        JsonToken token = jp.nextToken();
        switch (token) {
          case START_OBJECT:
          case START_ARRAY:
            depth++;
            break;
          case END_OBJECT:
          case END_ARRAY:
            depth--;
            break;
          case FIELD_NAME:
            jp.currentName();
            break;
          case VALUE_STRING:
            jp.getText();
            break;
          case VALUE_NUMBER_INT:
          case VALUE_NUMBER_FLOAT:
            jp.getLongValue();
            break;
          case VALUE_TRUE:
          case VALUE_FALSE:
            jp.getBooleanValue();
            break;
          case VALUE_NULL:
            // Do nothing; nextToken() will advance in stream
            break;
          default:
            throw new IllegalArgumentException("Unexpected token " + token);
        }
      } while (depth > 0);
      jp.close();
    }

